ORDER BY sheet_id;

MATCH (item:PlantItem {tag: 'P-201'})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (source:PlantItem)-[:send_to*1..]->(:PlantItem {tag: "TK-5301"})
WHERE NOT EXISTS {
  MATCH ()-[:send_to]->(source)
}
RETURN DISTINCT source.tag AS tag

MATCH (equipment:PlantItem {tag: "P-6201B"})-[:measured_by]->(instrument:PlantItem)
