ORDER BY instrument_tag;

MATCH (item:PlantItem:GravitationalSeparator)
WHERE item.unit_id = '46'
RETURN count(item.tag) AS count, collect(item.tag) AS tags}

MATCH (equipment:PlantItem {tag: 'P-1201A'})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (equipment:PlantItem {tag: 'P-2302'})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (controller:PlantItem {loop_tag: "BSL-39035"})-[:send_signal_to]->()-[:control]->(valve:PlantItem)
RETURN DISTINCT valve.tag AS tag
}

MATCH p = shortestPath((start:PlantItem {tag: 'EJ-4301B'})-[:send_to*]->(end:PlantItem {tag: 'EJ-4302A'}))
WITH [n IN nodes(p)[1..-1] WHERE any(label IN labels(n) WHERE label IN ['AngleBallValve', 'AngleGlobeValve', 'AnglePlugValve', 'AngleValve', 'BallValve', 'BreatherValve', 'ButterflyValve', 'CheckValve', 'GlobeCheckValve', 'GateValve', 'GlobeValve', 'NeedleValve', 'OperatedValve', 'PlugValve', 'SafetyValveOrFitting', 'SpringLoadedAngleGlobeSafetyValve', 'SpringLoadedGlobeSafetyValve', 'StraightwayValve', 'SwingCheckValve'])] AS valves
RETURN size(valves) AS valve_count, [valve IN valves | valve.tag] AS valve_tags;

MATCH (item:PlantItem {tag: 'EA-2501'})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (tank:PlantItem {tag: "T-501"})-[:send_to]-(valve:PlantItem)<-[:control]-(actuator:PlantItem)<-[:send_signal_to]-(controller:PlantItem)
RETURN DISTINCT controller.loop_tag AS loop_tag
WHERE controller.loop_tag IS NOT NULL;

MATCH (item:PlantItem {tag: "V-1901"})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (v:AngleBallValve:PlantItem)
WHERE v.unit_id = '10'
RETURN count(v) AS count, collect(v.tag) AS tags;

MATCH (e:PlantItem:AirEjector)
WHERE e.unit_id = '10'
RETURN count(e) AS count, collect(e.tag) AS tags;

MATCH (v:PlantItem:BallValve)
WHERE v.unit_id = '10'
RETURN count(v) AS ball_valve_count, collect(v.tag) AS tags;

MATCH (start:PlantItem {tag: 'P-601A'}), (end:PlantItem {tag: 'H-1201'})
RETURN start.tag AS from_tag, end.tag AS to_tag,
       EXISTS {
         MATCH p = (start)-[:send_to*]->(end)
         WHERE ALL(n IN nodes(p) WHERE n.tag IS NULL OR n.tag <> 'XV-7007')
       } AS can_flow_without_XV_7007;

MATCH (a:PlantItem {tag: 'V-5501'}), (b:PlantItem {tag: 'P-5501B'})
OPTIONAL MATCH p = shortestPath((a)-[:send_to*1..]->(b))
RETURN a.tag AS from_tag, b.tag AS to_tag, p IS NOT NULL AS can_reach;

MATCH (s:PlantItem {tag: 'TK-5101'}), (t:PlantItem {tag: 'E-5203'})
RETURN s.tag AS source_tag, t.tag AS destination_tag,
       EXISTS {
         MATCH p = (s)-[:send_to*0..]->(t)
         WHERE all(n IN nodes(p) WHERE n.tag IS NULL OR n.tag <> 'GTV-51012')
       } AS can_flow_without_GTV_51012

MATCH (source:PlantItem)-[:send_to*1..]->(valve:PlantItem {tag: 'V-201'})
WHERE NOT EXISTS {
  MATCH (:PlantItem)-[:send_to]->(source)
}
RETURN DISTINCT source.tag AS tag

MATCH (h:PlantItem {tag: 'H-2501'}), (e:PlantItem {tag: 'E-3102'})
RETURN EXISTS {
  MATCH p = (h)-[:send_to*1..]->(e)
  WHERE all(n IN nodes(p) WHERE n.tag IS NULL OR n.tag <> 'T-2701')
} AS can_flow_without_T_2701

MATCH (source:PlantItem)-[:send_to*1..]->(valve:PlantItem {tag: 'V-301'})
WHERE NOT EXISTS {
  MATCH (:PlantItem)-[:send_to]->(source)
}
RETURN DISTINCT source.tag AS tag

MATCH (target:PlantItem {tag: "P-801"})
MATCH (source:PlantItem)-[:send_to*1..]->(target)
WHERE NOT EXISTS {
  MATCH (:PlantItem)-[:send_to]->(source)
}
RETURN DISTINCT source.tag AS tag

MATCH (s:PlantItem {tag: "P-6001A"}), (t:PlantItem {tag: "D-1001"})
OPTIONAL MATCH p = shortestPath((s)-[:send_to*1..]->(t))
RETURN p IS NOT NULL AS can_reach, [n IN nodes(p) | n.tag] AS path_tags;

MATCH (s:PlantItem {tag: "EH-5201"}), (t:PlantItem {tag: "P-1601"}), p = shortestPath((s)-[:send_to*1..]->(t))
RETURN [n IN nodes(p) | n.tag] AS tags, length(p) AS path_length
LIMIT 1;

MATCH (s:PlantItem {tag: 'TK-3001'}), (e:PlantItem {tag: 'V-4703'})
MATCH p = shortestPath((s)-[:send_to*]->(e))
RETURN [n IN nodes(p) WHERE n = s OR n = e OR 'Equipment' IN labels(n) OR 'OperatedValve' IN labels(n) OR any(label IN labels(n) WHERE label ENDS WITH 'Valve') OR 'SafetyValveOrFitting' IN labels(n) | n.tag] AS path_tags;

MATCH p = (start:PlantItem {tag: 'P-6201A'})-[:send_to*]->(finish:PlantItem {tag: 'E-1002'})
WITH nodes(p) AS path
RETURN [n IN path WHERE 'Equipment' IN labels(n) OR any(label IN labels(n) WHERE label IN ['AngleBallValve', 'AngleGlobeValve', 'AnglePlugValve', 'AngleValve', 'BallValve', 'BreatherValve', 'ButterflyValve', 'CheckValve', 'GateValve', 'GlobeCheckValve', 'GlobeValve', 'NeedleValve', 'OperatedValve', 'PlugValve', 'SafetyValveOrFitting', 'SpringLoadedAngleGlobeSafetyValve', 'SpringLoadedGlobeSafetyValve', 'SwingCheckValve']) | n.tag] AS path_tags;

MATCH (start:PlantItem {tag: 'K-6001'}), (finish:PlantItem {tag: 'CHV-29004'})
MATCH p = shortestPath((start)-[:send_to*]->(finish))
RETURN [n IN nodes(p) WHERE 'Equipment' IN labels(n) OR any(label IN labels(n) WHERE label IN ['AngleBallValve', 'AngleGlobeValve', 'AnglePlugValve', 'AngleValve', 'BallValve', 'BreatherValve', 'ButterflyValve', 'CheckValve', 'GateValve', 'GlobeCheckValve', 'GlobeValve', 'NeedleValve', 'OperatedValve', 'PlugValve', 'SafetyValveOrFitting', 'SpringLoadedAngleGlobeSafetyValve', 'SpringLoadedGlobeSafetyValve', 'StraightwayValve', 'SwingCheckValve']) | n.tag] AS item_tags_in_order;

MATCH (item:PlantItem {tag: 'TI-15032'})
RETURN item.tag AS tag, labels(item) AS item_types, item.dexpi_class AS dexpi_class,
       item.category AS category, item.dexpi_labels AS dexpi_labels;

